function parseCohorts(text){ var lines=String(text).split('\n').map(function(l){return l.trim();}).filter(function(l){return l.length;});
  var data=[]; for(var i=0;i<lines.length;i++){ var vals=lines[i].split(/[\s,;]+/).map(function(x){return parseFloat(x);}); data.push(vals); }
  return data;
}
function retention(data){ if(!data.length) return []; var out=[];
  for(var i=0;i<data.length;i++){ var base=data[i][0]||1; var row=[]; for(var j=0;j<data[i].length;j++){ row.push(data[i][j]/base); } out.push(row); }
  return out;
}
var EXPORTS={parseCohorts:parseCohorts, retention:retention};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CohortForgePure = EXPORTS; }
